#!/usr/bin/env node
// Writes data/bundle.js: every file in data/ as one script, so index.html also works when opened
// straight from disk. When the site is served, the loader reads the YAML files directly and ignores this.
//   node tools/bundle.js
'use strict';
const fs = require('fs');
const path = require('path');
const dir = path.join(__dirname, '..', 'data');
const out = {};
for (const f of fs.readdirSync(dir).filter((x) => x.endsWith('.yaml')).sort()) out[f] = fs.readFileSync(path.join(dir, f), 'utf8');
fs.writeFileSync(path.join(dir, 'bundle.js'), '// Generated by tools/bundle.js. Do not edit; edit the YAML files and run it again.\n(globalThis.BBB = globalThis.BBB || {}).BUNDLE = ' + JSON.stringify(out) + ';\n');
console.log(`bundled ${Object.keys(out).length} files`);
